import React, { useState } from 'react';

export default function Chatbot(){
  const [open,setOpen] = useState(false);
  const [messages,setMessages] = useState([{from:'bot',text:'Hi! I am here to help.'}]);
  const [text,setText] = useState('');

  async function send(msg){
    setMessages(m=>[...m,{from:'user',text:msg}]);
    setText('');
    try{
      const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/chat', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({message:msg})});
      const data = await res.json();
      setMessages(m=>[...m,{from:'bot',text:data.reply,buttons:data.buttons}]);
    }catch(e){ setMessages(m=>[...m,{from:'bot',text:'Service unavailable'}]); }
  }

  return (
    <div className={`chatbot ${open?'open':''}`}>
      <div className="chat-toggle" onClick={()=>setOpen(o=>!o)}>{open?'Close Chat':'Chat with us'}</div>
      {open && (
        <div className="chat-window">
          <div className="messages">
            {messages.map((m,i)=> (
              <div key={i} className={`msg ${m.from}`}>
                <div>{m.text}</div>
                {m.buttons && <div className="buttons">{m.buttons.map((b,bi)=>(<button key={bi} onClick={()=>send(b)}>{b}</button>))}</div>}
              </div>
            ))}
          </div>
          <form onSubmit={(e)=>{e.preventDefault(); send(text);}} className="chat-input">
            <input value={text} onChange={e=>setText(e.target.value)} placeholder="Ask something" />
            <button type="submit">Send</button>
          </form>
        </div>
      )}
    </div>
  );
}
